        impl StatusOptions { # [doc = " Creates a new blank set of status options."] pub fn new () -> StatusOptions { unsafe { let mut raw = mem :: zeroed () ; let r = raw :: git_status_init_options (& mut raw , raw :: GIT_STATUS_OPTIONS_VERSION) ; assert_eq ! (r , 0) ; StatusOptions { raw , pathspec : Vec :: new () , ptrs : Vec :: new () , } } } # [doc = " Select the files on which to report status."] # [doc = ""] # [doc = " The default, if unspecified, is to show the index and the working"] # [doc = " directory."] pub fn show (& mut self , show : StatusShow) -> & mut StatusOptions { self . raw . show = match show { StatusShow :: Index => raw :: GIT_STATUS_SHOW_INDEX_ONLY , StatusShow :: Workdir => raw :: GIT_STATUS_SHOW_WORKDIR_ONLY , StatusShow :: IndexAndWorkdir => raw :: GIT_STATUS_SHOW_INDEX_AND_WORKDIR , } ; self } # [doc = " Add a path pattern to match (using fnmatch-style matching)."] # [doc = ""] # [doc = " If the `disable_pathspec_match` option is given, then this is a literal"] # [doc = " path to match. If this is not called, then there will be no patterns to"] # [doc = " match and the entire directory will be used."] pub fn pathspec < T : IntoCString > (& mut self , pathspec : T) -> & mut StatusOptions { let s = util :: cstring_to_repo_path (pathspec) . unwrap () ; self . ptrs . push (s . as_ptr ()) ; self . pathspec . push (s) ; self } fn flag (& mut self , flag : raw :: git_status_opt_t , val : bool) -> & mut StatusOptions { if val { self . raw . flags |= flag as c_uint ; } else { self . raw . flags &= ! (flag as c_uint) ; } self } # [doc = " Flag whether untracked files will be included."] # [doc = ""] # [doc = " Untracked files will only be included if the workdir files are included"] # [doc = " in the status \"show\" option."] pub fn include_untracked (& mut self , include : bool) -> & mut StatusOptions { self . flag (raw :: GIT_STATUS_OPT_INCLUDE_UNTRACKED , include) } # [doc = " Flag whether ignored files will be included."] # [doc = ""] # [doc = " The files will only be included if the workdir files are included"] # [doc = " in the status \"show\" option."] pub fn include_ignored (& mut self , include : bool) -> & mut StatusOptions { self . flag (raw :: GIT_STATUS_OPT_INCLUDE_IGNORED , include) } # [doc = " Flag to include unmodified files."] pub fn include_unmodified (& mut self , include : bool) -> & mut StatusOptions { self . flag (raw :: GIT_STATUS_OPT_INCLUDE_UNMODIFIED , include) } # [doc = " Flag that submodules should be skipped."] # [doc = ""] # [doc = " This only applies if there are no pending typechanges to the submodule"] # [doc = " (either from or to another type)."] pub fn exclude_submodules (& mut self , exclude : bool) -> & mut StatusOptions { self . flag (raw :: GIT_STATUS_OPT_EXCLUDE_SUBMODULES , exclude) } # [doc = " Flag that all files in untracked directories should be included."] # [doc = ""] # [doc = " Normally if an entire directory is new then just the top-level directory"] # [doc = " is included (with a trailing slash on the entry name)."] pub fn recurse_untracked_dirs (& mut self , include : bool) -> & mut StatusOptions { self . flag (raw :: GIT_STATUS_OPT_RECURSE_UNTRACKED_DIRS , include) } # [doc = " Indicates that the given paths should be treated as literals paths, note"] # [doc = " patterns."] pub fn disable_pathspec_match (& mut self , include : bool) -> & mut StatusOptions { self . flag (raw :: GIT_STATUS_OPT_DISABLE_PATHSPEC_MATCH , include) } # [doc = " Indicates that the contents of ignored directories should be included in"] # [doc = " the status."] pub fn recurse_ignored_dirs (& mut self , include : bool) -> & mut StatusOptions { self . flag (raw :: GIT_STATUS_OPT_RECURSE_IGNORED_DIRS , include) } # [doc = " Indicates that rename detection should be processed between the head."] pub fn renames_head_to_index (& mut self , include : bool) -> & mut StatusOptions { self . flag (raw :: GIT_STATUS_OPT_RENAMES_HEAD_TO_INDEX , include) } # [doc = " Indicates that rename detection should be run between the index and the"] # [doc = " working directory."] pub fn renames_index_to_workdir (& mut self , include : bool) -> & mut StatusOptions { self . flag (raw :: GIT_STATUS_OPT_RENAMES_INDEX_TO_WORKDIR , include) } # [doc = " Override the native case sensitivity for the file system and force the"] # [doc = " output to be in case sensitive order."] pub fn sort_case_sensitively (& mut self , include : bool) -> & mut StatusOptions { self . flag (raw :: GIT_STATUS_OPT_SORT_CASE_SENSITIVELY , include) } # [doc = " Override the native case sensitivity for the file system and force the"] # [doc = " output to be in case-insensitive order."] pub fn sort_case_insensitively (& mut self , include : bool) -> & mut StatusOptions { self . flag (raw :: GIT_STATUS_OPT_SORT_CASE_INSENSITIVELY , include) } # [doc = " Indicates that rename detection should include rewritten files."] pub fn renames_from_rewrites (& mut self , include : bool) -> & mut StatusOptions { self . flag (raw :: GIT_STATUS_OPT_RENAMES_FROM_REWRITES , include) } # [doc = " Bypasses the default status behavior of doing a \"soft\" index reload."] pub fn no_refresh (& mut self , include : bool) -> & mut StatusOptions { self . flag (raw :: GIT_STATUS_OPT_NO_REFRESH , include) } # [doc = " Refresh the stat cache in the index for files are unchanged but have"] # [doc = " out of date stat information in the index."] # [doc = ""] # [doc = " This will result in less work being done on subsequent calls to fetching"] # [doc = " the status."] pub fn update_index (& mut self , include : bool) -> & mut StatusOptions { self . flag (raw :: GIT_STATUS_OPT_UPDATE_INDEX , include) } # [allow (missing_docs)] pub fn include_unreadable (& mut self , include : bool) -> & mut StatusOptions { self . flag (raw :: GIT_STATUS_OPT_INCLUDE_UNREADABLE , include) } # [allow (missing_docs)] pub fn include_unreadable_as_untracked (& mut self , include : bool) -> & mut StatusOptions { self . flag (raw :: GIT_STATUS_OPT_INCLUDE_UNREADABLE_AS_UNTRACKED , include) } # [doc = " Set threshold above which similar files will be considered renames."] # [doc = ""] # [doc = " This is equivalent to the `-M` option. Defaults to 50."] pub fn rename_threshold (& mut self , threshold : u16) -> & mut StatusOptions { self . raw . rename_threshold = threshold ; self } # [doc = " Get a pointer to the inner list of status options."] # [doc = ""] # [doc = " This function is unsafe as the returned structure has interior pointers"] # [doc = " and may no longer be valid if these options continue to be mutated."] pub unsafe fn raw (& mut self) -> * const raw :: git_status_options { self . raw . pathspec . strings = self . ptrs . as_ptr () as * mut _ ; self . raw . pathspec . count = self . ptrs . len () as size_t ; & self . raw } }
